<?php
require_once __DIR__ . '/includes/functions.php';
$user=require_login(); $pageTitle='Your profile'; $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    csrf_check(); $name=trim($_POST['name'] ?? ''); $phone=trim($_POST['phone'] ?? ''); $address=trim($_POST['address'] ?? ''); $newPassword=(string)($_POST['new_password']??''); $newHash=null;
    if($newPassword!==''){$hashQuery=db()->prepare('SELECT password_hash FROM users WHERE id=?');$hashQuery->execute([$user['id']]);$oldHash=(string)$hashQuery->fetchColumn();if(strlen($newPassword)<8)$error='Your new password must be at least 8 characters.';elseif(!password_verify((string)($_POST['current_password']??''),$oldHash))$error='Enter your current password to change it.';else$newHash=password_hash($newPassword,PASSWORD_DEFAULT);}
    if (mb_strlen($name)<2) $error='Please enter your name.';
    if (!$error) { $stmt=db()->prepare('UPDATE users SET name=?,phone=?,address=? WHERE id=?'); $stmt->execute([$name,$phone,$address,$user['id']]); if($newHash)db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([$newHash,$user['id']]); $_SESSION['user']['name']=$name; $_SESSION['user']['phone']=$phone; $_SESSION['user']['address']=$address; flash('Your profile has been updated.'); redirect('profile.php'); }
}
$stmt=db()->prepare('SELECT * FROM users WHERE id=?'); $stmt->execute([$user['id']]); $profile=$stmt->fetch();
require __DIR__ . '/includes/header.php'; ?>
<section class="page-shell"><div class="page-heading"><span class="eyebrow">YOUR ACCOUNT</span><h1>A little <em>about you.</em></h1><p>Keep your contact details and delivery address up to date.</p></div><div class="content-card profile-card"><span class="eyebrow">PROFILE DETAILS</span><h2><?= e($profile['email']) ?></h2><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Full name<input name="name" required value="<?= e($_POST['name']??$profile['name']) ?>"></label><label>Phone number<input type="tel" name="phone" value="<?= e($_POST['phone']??$profile['phone']) ?>"></label><label>Saved delivery address<textarea name="address" rows="4" placeholder="Building, street, township…"><?= e($_POST['address']??$profile['address']) ?></textarea></label><details class="password-change"><summary>Change password</summary><label>Current password<input type="password" name="current_password" autocomplete="current-password"></label><label>New password<input type="password" name="new_password" minlength="8" autocomplete="new-password"><small>Leave blank to keep your current password.</small></label></details><button class="button button-dark">Save profile</button></form><a class="inline-link" href="orders.php">See your order history ↗</a></div></section>
